try:
    print('>>> x = frozenset()')
    print('>>> y = 3')
    print('>>> x -= y')
    print('>>> x')
    x = frozenset()
    y = 3
    x -= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
